    return [t,1/((1+a*x)*v),np.exp(-b*x**2)]
def fit(extra_fn, p0):
    def res(p):
        A=np.column_stack(base(p[0],p[1])+[extra_fn(p[2:])])
        c=np.linalg.lstsq(A,y,rcond=None)[0]
        return y-A@c
    best=None
    for s0 in p0:
        try:
            r=least_squares(res,s0)
            s=np.sum(r.fun**2)
            if best is None or s<best[0]: best=(s,r.x)
        except Exception: pass
    return best
