from scipy.optimize import least_squares
t,x,v,y=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
tot=np.sum((y-y.mean())**2)
knots=np.linspace(0.5,8,12)
def hats(tt):
    H=[]
    for i,k in enumerate(knots):
        h=knots[1]-knots[0]
        H.append(np.clip(1-np.abs(tt-k)/h,0,None))
    return np.column_stack(H)
def res(p,pw):
    A=np.column_stack([t,1/((1+p[0]*x)*v),np.exp(-p[1]*x**2),hats(t)*(v**pw)[:,None]])
    c=np.linalg.lstsq(A,y,rcond=None)[0]
    return y-A@c, c
for pw in [2,3,2.5,3.5]:
